<script module lang="ts">
/**
 * List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/list.module.css'

export interface ListItemProps {
  /**
   * The item whose page or detail is open. At most one per list. It has no effect on an item
   * that is only read, which has no link or button to say it to a screen reader.
   */
  current?: boolean
  /**
   * One supporting line under the title. It wraps and is never clipped.
   */
  description?: string
  /**
   * The item navigates: the title is a link whose target covers the row.
   */
  href?: string
  /**
   * One mark before the text: an Avatar, an Icon or an Image. Not a control.
   */
  leading?: Snippet
  /**
   * A short trailing fact the application has already formatted: a time, a count.
   */
  meta?: string
  /**
   * The app's router, on an item with an `href`, as on Link (`link.md` §Routing): a click that
   * would navigate this tab calls it in place of the browser.
   */
  onNavigate?: (href: string) => void
  /**
   * The item is picked. Without an `href` the title is a button whose target covers the row.
   * With one it is also called on every click of the link, one that opens a new tab included, so
   * a router uses `onNavigate` there.
   */
  onSelect?: () => void
  /**
   * The item's name, and the accessible name of its link or button.
   */
  title: string
  /**
   * One governed member after the text: a Badge, a Button, a Menu or a Switch. A control takes
   * its own press. A press on anything else in it is a press on the row.
   */
  trailing?: Snippet
}
</script>

<script lang="ts">
let {
  current = false,
  description,
  href,
  leading,
  meta,
  onNavigate,
  onSelect,
  title,
  trailing,
}: ListItemProps = $props()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get navigate() {
    return onNavigate !== undefined
  },
  get select() {
    return onSelect !== undefined
  },
}
const slots = {
  get leading() {
    return leading
  },
  get trailing() {
    return trailing
  },
}
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const route = $derived((event: MouseEvent): void => {
  if (href === undefined || !listening.navigate || !navigatesHere(event)) return
  event.preventDefault()
  onNavigate?.(href)
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li
    class={styles.item}
    data-interactive={(href !== undefined || listening.select) ? '' : undefined}
    data-current={(current && (href !== undefined || listening.select)) ? '' : undefined}
    >{#if slots.leading}<span class={styles.leading}>{@render leading?.()}</span>{/if
    }<span class={styles.text}
      >{#if href !== undefined
        }<a
          class={[styles.title, styles.primary]}
          {href}
          aria-current={(current) ? 'page' : undefined}
          onclick={(event) => { (onSelect?.(), route(event)) }}
          >{title
        }</a
      >{:else if listening.select
        }<button
          class={[styles.title, styles.primary]}
          type="button"
          aria-current={(current) ? 'true' : undefined}
          onclick={() => { onSelect?.() }}
          >{title
        }</button
      >{:else
        }<span class={styles.title}>{title}</span
      >{/if
      }{#if description !== undefined}<span class={styles.description}>{description}</span>{/if
    }</span
    >{#if meta !== undefined}<span class={styles.meta}>{meta}</span>{/if
    }{#if slots.trailing}<span class={styles.trailing}>{@render trailing?.()}</span>{/if
  }</li
>{/if
}{@render joined.end?.()}
